set-variable.value:
@{
    var decision = JObject.Parse((string)context.Variables["gatewayDecision"]);
    if (!(bool)decision["allowed"] || !context.Variables.ContainsKey("gatewayEntraAuthenticationValidated")
        || !(bool)context.Variables["gatewayEntraAuthenticationValidated"]) { throw new Exception("Verified employee is required"); }
    var user = JObject.Parse((string)context.Variables["gatewayUserAuthentication"]);
    if ((string)decision["callerId"] != (string)user["callerId"] || (string)decision["allocationId"] != (string)user["allocationId"]) { throw new Exception("Verified employee is required"); }
    var limits = user["limits"] as JObject;
    if (limits == null || limits.Properties().Count() != 3 || !context.Variables.ContainsKey("gatewayEntraUserLimits")
        || !JToken.DeepEquals(limits, JObject.Parse((string)context.Variables["gatewayEntraUserLimits"]))) { throw new Exception("Configured employee limits are required"); }
    var rate = limits["requestRate"]; var tpm = limits["tokensPerMinute"]; var quota = limits["tokenQuota"];
    if (rate == null || tpm == null || quota == null) { throw new Exception("Complete employee limits are required"); }
    if (rate.Type != JTokenType.Null && (rate.Type != JTokenType.Object || ((JObject)rate).Properties().Count() != 2
        || rate["calls"]?.Type != JTokenType.Integer || (long)rate["calls"] < 1 || (long)rate["calls"] > 1000000
        || rate["renewalPeriodSeconds"]?.Type != JTokenType.Integer || (long)rate["renewalPeriodSeconds"] < 1 || (long)rate["renewalPeriodSeconds"] > 300)) { throw new Exception("Valid employee request limit is required"); }
    if (tpm.Type != JTokenType.Null && (tpm.Type != JTokenType.Integer || (long)tpm < 1 || (long)tpm > 2147483647)) { throw new Exception("Valid employee token rate is required"); }
    if (quota.Type != JTokenType.Null && (quota.Type != JTokenType.Object || ((JObject)quota).Properties().Count() != 2
        || quota["tokens"]?.Type != JTokenType.Integer || (long)quota["tokens"] < 1 || (long)quota["tokens"] > 2147483647
        || quota["period"]?.Type != JTokenType.String
        || !new [] { "Hourly", "Daily", "Weekly", "Monthly", "Yearly" }.Contains((string)quota["period"]))) { throw new Exception("Valid employee token quota is required"); }
    return limits.ToString(Newtonsoft.Json.Formatting.None);
  }
